# Production configuration for Brew (feed.joinsquareup.com), sourced by tools/promote.sh. One place, so web and worker
# always run with the same settings. Production is clean: never DEMO_MODE, AI_MOCK, OPEN_SITE or DEV_LOGIN (prod-clean.mjs
# checks the live services for these too).
P=squareup-492617; REGION=asia-south1; SA=brew-runtime@squareup-492617.iam.gserviceaccount.com
PROD_URL=https://feed.joinsquareup.com
# shared by both services; ROLE is added per service
PROD_ENV="^|^ENV=production|GOOGLE_CLOUD_PROJECT=$P|META_GRAPH_VERSION=v26.0|GEMINI_IMAGE_MODEL=gemini-2.5-flash-image|DAILY_TEXT_CAP=1500|DAILY_IMAGE_CAP=1500|DAILY_VIDEO_CAP=60|BRAND_VIDEO_CAP=20|RESEARCH_BUCKET=brew-prod|TREG_ORG=squareup|TREG_DAY_CAP_USD=40|APIFY_BRAND_MONTH_CAP_USD=10|BUILD_CAP_USD=45|DAILY_BUILD_CAP_USD=250|PUBLIC_URL=$PROD_URL|MOVES_CONCURRENCY=8|BUILD_BLOCK=wearcomet-in,everaw-in|ADMIN_EMAILS=param@joinsquareup.com|FULL_ACCESS_DOMAINS=joinsquareup.com,shopos.ai|PROTECTED_CONNECTIONS=arata-in|BUILD_SIGNIN=1|TRUSTED_PROXY_HOPS=1|FEED_SIGNIN=1|GA4_SA_EMAIL=$SA|SHOPIFY_OAUTH=0|GOOGLE_OAUTH=1|META_ADS_CONFIG_ID=2157080375167128|AI_PROVIDER=gemini|GEMINI_DEEP_MODEL=gemini-3.5-flash|GEMINI_FAST_MODEL=gemini-3.5-flash|GEMINI_MOVES_MODEL=gemini-3.1-pro-preview|BUILD_CONFIRM_WAIT_MS=900000|STORAGE=pg|OBJECTS_READTHROUGH=0|OBJECTS_MIRROR=0|RETIRE_OFF=1|UV_THREADPOOL_SIZE=16|DEMO_URL=https://demo.joinsquareup.com"
PROD_SECRETS="DATABASE_URL=BREW_PROD_DATABASE_URL:latest,FEED_SESSION_SECRET=FEED_SESSION_SECRET_PROD:latest,HANDOFF_SECRET=HANDOFF_SECRET_PROD:latest,FEED_VAULT_KEY=FEED_VAULT_KEY_PROD:latest,ANTHROPIC_API_KEY=ANTHROPIC_API_KEY:latest,OPENAI_API_KEY=OPENAI_API_KEY:latest,TREG_TOKEN=TREG_TOKEN:latest,YOUTUBE_API_KEY=YOUTUBE_API_KEY:latest,RESEND_API_KEY=RESEND_API_KEY:latest,GOOGLE_CLIENT_ID=GOOGLE_CLIENT_ID:latest,GOOGLE_CLIENT_SECRET=GOOGLE_CLIENT_SECRET:latest,FEED_SHOPIFY_CLIENT_ID=FEED_SHOPIFY_CLIENT_ID:latest,FEED_SHOPIFY_CLIENT_SECRET=FEED_SHOPIFY_CLIENT_SECRET:latest,META_ADS_OAUTH_CLIENT_ID=META_ADS_OAUTH_CLIENT_ID:latest,META_ADS_OAUTH_CLIENT_SECRET=META_ADS_OAUTH_CLIENT_SECRET:latest,GOOGLE_ADS_OAUTH_CLIENT_ID=GOOGLE_ADS_OAUTH_CLIENT_ID:latest,GOOGLE_ADS_OAUTH_CLIENT_SECRET=GOOGLE_ADS_OAUTH_CLIENT_SECRET:latest,GOOGLE_ADS_DEVELOPER_TOKEN=GOOGLE_ADS_DEVELOPER_TOKEN:latest,SLACK_CLIENT_ID=SLACK_CLIENT_ID:latest,SLACK_CLIENT_SECRET=SLACK_CLIENT_SECRET:latest,SLACK_SIGNING_SECRET=SLACK_SIGNING_SECRET:latest,PAGESPEED_API_KEY=PAGESPEED_API_KEY:latest"
gcloud secrets describe APIFY_TOKEN --project=$P >/dev/null 2>&1 && PROD_SECRETS="$PROD_SECRETS,APIFY_TOKEN=APIFY_TOKEN:latest"
gcloud secrets describe HF_API_KEY_SECRET --project=$P >/dev/null 2>&1 && PROD_SECRETS="$PROD_SECRETS,HF_API_KEY_ID=HF_API_KEY_ID:latest,HF_API_KEY_SECRET=HF_API_KEY_SECRET:latest"
NET="--network=default --subnet=default --vpc-egress=private-ranges-only"
